using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Automation;
using System.Windows.Automation.Peers;
using System.Windows.Controls;
using System.Windows.Input;
using Aingel.Desktop.Core;

namespace Aingel.Desktop;

/// <summary>
/// A PDF (or a page photo) read page by page (backend assistance.documents). The page text is the PDF's own; scanned
/// pages are transcribed by AI only when asked, and explanations are marked as generated by AI.
/// </summary>
public partial class DocumentWindow : Window
{
    public sealed record Entry(string Label, int Page);

    readonly App app;
    readonly Profile profile;
    readonly Speech speech;
    readonly string token;
    readonly int pages;
    readonly bool synthetic;
    int current = 1;
    string pageText = "";
    bool hasText, busy;

    string T(string key, params object[] args) => Texts.Get(profile.Locale, key, args);

    public DocumentWindow(App app, Profile profile, Speech speech, JsonElement opened)
    {
        this.app = app;
        this.profile = profile;
        this.speech = speech;
        InitializeComponent();
        token = opened.GetProperty("document").GetString()!;
        pages = opened.GetProperty("pages").GetInt32();
        synthetic = opened.TryGetProperty("synthetic_fixture", out var fixture) && fixture.ValueKind == JsonValueKind.String;
        var title = opened.GetProperty("title").GetString();
        Title = Heading.Text = string.IsNullOrWhiteSpace(title) ? T("doc_untitled") : title;
        var chapters = opened.GetProperty("outline").EnumerateArray()
            .Select(row => new Entry($"{row.GetProperty("title").GetString()} · {T("doc_page_short")} {row.GetProperty("page").GetInt32()}", row.GetProperty("page").GetInt32()))
            .ToList();
        Chapters.ItemsSource = chapters;
        Chapters.IsEnabled = chapters.Count > 0;
        PreviousButton.Content = T("doc_previous");
        NextButton.Content = T("doc_next");
        GoLabel.Content = "_" + T("doc_go_to");
        GoButton.Content = T("doc_go");
        ChaptersLabel.Content = "_" + T(chapters.Count > 0 ? "doc_chapters" : "doc_no_chapters");
        ReadButton.Content = T("doc_read");
        StopButton.Content = T("stop_speech");
        TranscribeButton.Content = T("doc_transcribe");
        ExplainButton.Content = T("doc_explain");
        SummarizeButton.Content = T("doc_summarize");
        FiguresButton.Content = T("doc_figures");
        WholeButton.Content = T("doc_whole");
        QuestionLabel.Content = "_" + T("doc_question");
        AskButton.Content = T("ask");
        SearchLabel.Content = "_" + T("doc_search");
        SearchButton.Content = T("doc_search_button");
        CloseButton.Content = T("doc_close");
        // Labels do not name their controls for UI Automation in WPF: each input gets its name here.
        AutomationProperties.SetName(GoTo, T("doc_go_to"));
        AutomationProperties.SetName(Chapters, T("doc_chapters"));
        AutomationProperties.SetName(Question, T("doc_question"));
        AutomationProperties.SetName(Query, T("doc_search"));
        AutomationProperties.SetName(Results, T("doc_results"));
        // Typed text is free content: never sent with a synthetic document.
        Question.IsEnabled = AskButton.IsEnabled = !synthetic;
        Loaded += async (_, _) => { await Show(1); Page.Focus(); };
        Closed += async (_, _) => { speech.Stop(); await app.Api!.CloseDocument(token); };
    }

    void Say(string text)
    {
        Status.Text = text;
        UIElementAutomationPeer.FromElement(Status)?.RaiseAutomationEvent(AutomationEvents.LiveRegionChanged);
    }

    async Task Guard(Func<Task> work)
    {
        if (busy) return;
        busy = true;
        try { await work(); }
        catch (ApiFailure failure)
        {
            Say(Texts.Error(profile.Locale, failure.Code));
            if (failure.Code is "document_expired" or "consent_changed" or "camera_consent_revoked") Close();
        }
        finally { busy = false; }
    }

    Task Show(int number) => Guard(() => Load(number));

    async Task Load(int number)
    {
        number = Math.Clamp(number, 1, pages);
        var page = await app.Api!.DocumentPage(token, number);
        current = number;
        hasText = page.GetProperty("has_text").GetBoolean();
        pageText = page.GetProperty("text").GetString() ?? "";
        var chapter = page.TryGetProperty("chapter", out var value) && value.ValueKind == JsonValueKind.String ? value.GetString() : null;
        var header = T("doc_page_of", number, pages) + (chapter != null ? " · " + chapter : "");
        var note = page.GetProperty("transcribed").GetBoolean() ? T("doc_transcribed_note") + "\n\n" : "";
        Page.Text = header + "\n\n" + note + (hasText ? pageText : T("doc_scanned"));
        Page.CaretIndex = 0;
        GoTo.Text = number.ToString();
        PreviousButton.IsEnabled = number > 1;
        NextButton.IsEnabled = number < pages;
        TranscribeButton.Visibility = hasText ? Visibility.Collapsed : Visibility.Visible;
        Say(header);
    }

    Task Ask(string action, string label, string scope = "page", string? question = null) => Guard(async () =>
    {
        Say(T("thinking"));
        var answer = await app.Api!.AskDocument(token, action, current, scope, question);
        var text = answer.GetProperty("text").GetString() ?? "";
        if (answer.TryGetProperty("mode", out var mode) && mode.GetString() == "mock") text = T("mock_note") + " " + text;
        Page.Text = $"{label} ({T("doc_ai")})\n\n{text}\n\n— {T("doc_page_of", current, pages)} —\n\n{(hasText ? pageText : "")}";
        Page.CaretIndex = 0;
        Say(label);
        speech.Speak(text);
    });

    async void OnPrevious(object sender, RoutedEventArgs e) => await Show(current - 1);
    async void OnNext(object sender, RoutedEventArgs e) => await Show(current + 1);
    async void OnGo(object sender, RoutedEventArgs e) { if (int.TryParse(GoTo.Text, out var page)) await Show(page); }
    void OnGoKey(object sender, KeyEventArgs e) { if (e.Key == Key.Enter) { e.Handled = true; OnGo(sender, e); } }
    async void OnChapter(object sender, SelectionChangedEventArgs e) { if (Chapters.SelectedItem is Entry entry && entry.Page != current) await Show(entry.Page); }
    void OnRead(object sender, RoutedEventArgs e) { if (hasText) speech.Speak(pageText); else Say(T("doc_scanned")); }
    void OnStop(object sender, RoutedEventArgs e) => speech.Stop();

    async void OnTranscribe(object sender, RoutedEventArgs e) => await Guard(async () =>
    {
        Say(T("doc_transcribing"));
        var result = await app.Api!.TranscribePage(token, current);
        if (result.TryGetProperty("mode", out var mode) && mode.GetString() == "mock") { Say(T("mock_note")); return; }
        await Load(current);
    });

    async void OnExplain(object sender, RoutedEventArgs e) => await Ask("explain", T("doc_explain"));
    async void OnSummarize(object sender, RoutedEventArgs e) => await Ask("summarize", T("doc_summarize"));
    async void OnFigures(object sender, RoutedEventArgs e) => await Ask("figures", T("doc_figures"));
    async void OnWhole(object sender, RoutedEventArgs e) => await Ask("summarize", T("doc_whole"), "document");

    async void OnAsk(object sender, RoutedEventArgs e)
    {
        var question = Question.Text.Trim();
        if (question.Length > 0) await Ask("question", question, "document", question);
    }

    void OnQuestionKey(object sender, KeyEventArgs e) { if (e.Key == Key.Enter) { e.Handled = true; OnAsk(sender, e); } }

    async void OnSearch(object sender, RoutedEventArgs e) => await Guard(async () =>
    {
        var query = Query.Text.Trim();
        if (query.Length < 2) return;
        var found = await app.Api!.SearchDocument(token, query);
        var rows = found.GetProperty("results").EnumerateArray()
            .Select(hit => new Entry($"{T("doc_page_short")} {hit.GetProperty("page").GetInt32()}: {hit.GetProperty("excerpt").GetString()}", hit.GetProperty("page").GetInt32()))
            .ToList();
        Results.ItemsSource = rows;
        Say(rows.Count == 0 ? T("doc_not_found") : T("doc_found", rows.Count));
        if (rows.Count > 0) Results.Focus();
    });

    void OnSearchKey(object sender, KeyEventArgs e) { if (e.Key == Key.Enter) { e.Handled = true; OnSearch(sender, e); } }
    async void OnResult(object sender, MouseButtonEventArgs e) { if (Results.SelectedItem is Entry entry) await Show(entry.Page); }
    async void OnResultKey(object sender, KeyEventArgs e) { if (e.Key == Key.Enter && Results.SelectedItem is Entry entry) { e.Handled = true; await Show(entry.Page); } }
    void OnCloseDocument(object sender, RoutedEventArgs e) => Close();

    /// <summary>The fields for opening a document, as for a screen capture (the server checks the authorization).</summary>
    internal static Dictionary<string, string> OpenFields(Profile profile, bool privateTest, string? fixture)
    {
        if (fixture != null) return new Dictionary<string, string> { ["locale"] = profile.Locale, ["fixture"] = fixture };
        var fields = new Dictionary<string, string> { ["locale"] = profile.Locale, ["profile"] = profile.Id };
        if (privateTest)
        {
            if (!VisionFields.PrivateTestAllowed(profile)) throw new ApiFailure("private_test_consent_required");
            fields["private_test"] = "true";
        }
        return fields;
    }
}
